import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    c = close.to_numpy()
    ema8 = np.zeros(len(c))
    ema24 = np.zeros(len(c))
    ema8[0] = ema24[0] = c[0]
    for t in range(1, len(c)):
        ema8[t] = 0.2 * c[t] + 0.8 * ema8[t-1]
        ema24[t] = 0.0417 * c[t] + 0.9583 * ema24[t-1]

    pos = np.zeros(len(c), dtype=int)
    for t in range(len(c)):
        if t < 8:
            pos[t] = 0
        else:
            if ema8[t] > ema24[t]:
                pos[t] = 1
            else:
                pos[t] = 0
    return pd.Series(pos, index=df.index)
