import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    c = close.to_numpy()
    sma = close.rolling(15).mean().to_numpy()

    pos = np.zeros(len(c), dtype=int)
    for t in range(len(c)):
        if np.isnan(sma[t]):
            pos[t] = 0
        else:
            pos[t] = 1 if c[t] > sma[t] else -1 if c[t] < sma[t] else 0
    return pd.Series(pos, index=df.index)
