import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    c = close.to_numpy()
    change = np.diff(c)
    gain = np.maximum(change, 0)
    loss = np.maximum(-change, 0)
    avg_gain = np.cumsum(gain) / 16
    avg_loss = np.cumsum(loss) / 16
    rsi = 100 - 100 / (1 + avg_gain / avg_loss)
    rsi = np.where(avg_loss == 0, 100, rsi)
    rsi = np.pad(rsi, (1, 0), mode='constant')
    pos = np.zeros(len(c), dtype=int)
    state = 0
    for t in range(len(c)):
        if np.isnan(rsi[t]):
            state = 0
        elif state == 0:
            if rsi[t] < 28:
                state = 1
            elif rsi[t] > 72:
                state = -1
        elif state == 1:
            if rsi[t] > 52:
                state = 0
        elif state == -1:
            if rsi[t] < 52:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
