import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    c = close.to_numpy()
    avg_gain = np.zeros(len(c))
    avg_loss = np.zeros(len(c))
    avg_gain[1] = c[1] - c[0]
    avg_loss[1] = abs(c[1] - c[0])
    for t in range(2, len(c)):
        gain = max(c[t] - c[t-1], 0)
        loss = max(-c[t] + c[t-1], 0)
        avg_gain[t] = avg_gain[t-1] + (gain - avg_gain[t-1]) / 6
        avg_loss[t] = avg_loss[t-1] + (loss - avg_loss[t-1]) / 6
        rsi = 100 - 100 / (1 + avg_gain[t] / avg_loss[t])
        if np.isnan(rsi):
            rsi = 50.0
        rsi = np.where(avg_loss[t] == 0, 50.0, rsi)
    pos = np.zeros(len(c), dtype=int)
    state = 0
    for t in range(len(c)):
        if np.isnan(rsi[t]):
            state = 0
        elif state == 0:
            if rsi[t] < 28:
                state = 1
        elif state == 1:
            if rsi[t] > 45:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
