        avg_gain[t] = np.clip(avg_gain[t], 0, None)
        avg_loss[t] = np.clip(avg_loss[t], 0, None)
        rsi = 100 - 100 / (1 + avg_gain[t] / avg_loss[t])
        rsi = np.where(avg_loss[t] == 0, 100, rsi)
        pos = np.zeros(len(c), dtype=int)
        state = 0
        for t2 in range(len(c)):
            if state == 0:
                if rsi[t2] < 35:
                    state = 1
                elif rsi[t2] > 65:
                    state = -1
            elif state == 1:
                if rsi[t2] > 52:
                    state = 0
            elif state == -1:
