import numpy as np
import pandas as pd


def generate_signals(df):
    high = df["high"]
    low = df["low"]
    c = df["close"].to_numpy()
    prior_high = high.rolling(60).max().shift(1).to_numpy()
    prior_low = low.rolling(60).min().shift(1).to_numpy()

    pos = np.zeros(len(c), dtype=int)
    for t in range(len(c)):
        if np.isnan(prior_high[t]) or np.isnan(prior_low[t]):
            pos[t] = 0
        elif c[t] > prior_high[t]:
            pos[t] = 1
        elif c[t] < prior_low[t]:
            pos[t] = 0
        else:
            pos[t] = pos[t - 1]
    return pd.Series(pos, index=df.index)
