    c = close.to_numpy()
    sma = close.rolling(120).mean().to_numpy()
    rsi = np.zeros(len(c))
    gain = np.maximum(c[1:] - c[:-1], 0)
    loss = np.maximum(-c[1:] + c[:-1], 0)
    avg_gain = np.zeros(len(c))
    avg_loss = np.zeros(len(c))
    avg_gain[1] = gain[1]
    avg_loss[1] = loss[1]
