            elif c[t] < sma[t] and (t == 0 or c[t-1] >= sma[t-1]):
                state, trough = -1, c[t]
        elif state == 1:
            if c[t] < peak * (1 - 0.05):
                state = 0
        elif state == -1:
            if c[t] > trough * (1 + 0.05):
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
